async function call(path,{method='GET',body}={}){const r=await fetch(API+path,{method,credentials:'same-origin',cache:'no-store',headers:method==='GET'?{}:{'X-PWA-CSRF':'1'},body});let data;try{data=await r.json();}catch{throw Error('Git service HTTP '+r.status);}if(!r.ok){if(r.status===403&&/Administrator unlock/.test(data.error||'')){unlock=false;expiresAt=null;markLocks();const label=root.querySelector('.gm-admin');if(label){label.innerHTML='Administrator locked · <button data-act="nav" data-id="settings">Unlock in Settings</button>';label.classList.remove('unlocked');}}throw Error(data.error||'HTTP '+r.status);}return data;}
