const countJob=j=>{const total=j.mode==='export'?(j.exportSpec?.repositories?.length||0):j.plan.updates.length;const done=j.mode==='export'?(j.status==='completed'?total:j.progress?.done||0):j.index;return [Math.min(done,total),total];};
function progressText(){const live=jobsCache.filter(j=>j.status==='running'||j.status==='paused'&&j.retryAt);const counts=live.map(countJob);return live.length?counts.reduce((a,x)=>a+x[0],0)+'/'+counts.reduce((a,x)=>a+x[1],0):'';}
