 const profileCards=profiles.map(p=>`<details class="gm-card gm-usage-card" ${p.id===registry?.active?'open':''}><summary><strong>${e(p.name)}${p.id===registry?.active?' · Active':''}</strong></summary><small>${p.pending?'Includes local usage not yet synchronized.':Object.keys(p.month).length?'Local and cloud-backed observations merged without duplication.':'No cloud-linked profile activity recorded this month.'}</small>${Object.keys(p.month).length?`<h4>Month to date (UTC)</h4>${profileMetrics(p.month)}${Object.keys(p.today).length?expandable('Today',profileMetrics(p.today)):''}`:''}${Object.keys(p.localOnly).length?expandable('Unlinked local-only usage',profileMetrics(p.localOnly)):''}</details>`).join('');
 return `<h2>Usage</h2><p class="muted">Account allowances and profile usage are separate. Profile observations never increase provider totals.</p><button class="primary gm-full" data-act="usage-refresh">Refresh usage</button><small role="status">${force?provider?.at?(reused?'Recent provider readings reused · ':'Refresh checked · '):'Refresh incomplete · ':''}${provider?.at?'Provider readings checked '+e(localTime(provider.at)):'Provider readings unavailable.'}</small><h3>Account-wide allowances</h3>${usageCards}<h3>Profile usage</h3><small>New measurements begin with R12. UTC month; no historical attribution. Only observed profile activity, not provider billing.</small>${remote?'':'<p class="gm-warn">Cloud profile usage unavailable; only unlinked local observations may be shown.</p>'}${sync&&sync.state!=='up-to-date'?`<p class="gm-warn">Profile sync: ${e(sync.state)}${sync.pending?' · '+e(sync.pending)+' pending snapshots':''}. Local counters are retained.</p>`:sync?`<small>Profile sync checked${sync.uploaded?' · '+e(sync.uploaded)+' snapshots uploaded':''}.</small>`:''}${profileCards||'<p>No profiles or measurements available.</p>'}${card('Usage backup',row('Last verified',t?.regularUsageLastBackup?localTime(t.regularUsageLastBackup):null)+row('Next scheduled',t?.regularUsageNextBackup?localTime(t.regularUsageNextBackup):null)+(t?.regularUsageBackupError?'<p class="gm-warn">Backup verification failed; retry scheduled.</p>':'')+expandable('Account-wide application estimates',row('Translation characters',u.month.translate?.characters)+row('Speech characters',u.month.speech?.characters)+row('Drive calls',u.month.drive?.driveCalls)))}<button class="gm-full" data-act="nav" data-id="settings">Back to Settings</button>`;
