async function render(){if(loading)return;loading=true;try{await checkAdmin();if(view!=='activity')try{jobsCache=await call('/jobs');}catch{}if(view==='repos'){if(selected)await repoDetail();else{await loadRepos();html(repoCards());}}else if(view==='updates'){if(!repos.length)await loadRepos();form();}else if(view==='activity')await showActivity();else if(view==='telemetry'){html(await telemetryPage());updateRange();}else if(view==='usage')html(await usagePage());else html(`<h2>Administrator settings</h2><p>Google session identifies the authorized account. Administrator access is validated by the server and expires after 4 hours. The password is sent only when unlocking; subsequent operations use a secure session cookie.</p><label>Unlock phrase<input id="gm-unlock" type="password" autocomplete="off"></label><div class="gm-buttons"><button data-act="unlock">Unlock for 4 hours</button><button data-act="lock">Lock</button></div><p>${unlock?'Administrator access unlocked until '+e(localTime(expiresAt)):'Administrator access locked.'}</p><button class="gm-full" data-act="nav" data-id="usage">Usage</button><p class="muted">Use the profile button to manage Google Drive.</p>`);}catch(err){html('<p>Unable to load. Check connection, Worker bindings and authorization.</p><button data-act="refresh">Retry</button> <a class="gm-link gm-full" href="/_profiles/v1/auth/start?return='+encodeURIComponent(location.pathname+location.search)+'">Connect Google Drive</a>');error(err);}finally{loading=false;}}
let preparedTelemetry=null;
async function prepareTelemetry(query,activity=null,zone='UTC',uploadFirst=false,throughNow=false){
 preparedTelemetry=null;let uploadOutcome=null;if(uploadFirst){try{const f=await call('/telemetry/lifecycle',{method:'POST',body:JSON.stringify({action:'flush'})});uploadOutcome=f.enabled?'drained':'disabled';}catch{uploadOutcome='incomplete';}if(activity)query=activityQuery(activity);else if(throughNow)query={...query,end:new Date().toISOString()};}let status;try{status=await call('/telemetry/status');}catch{status={error:'status-unavailable'};}
 const report=await prepareArchive(query,{activity,status,zone,readPage:q=>call('/telemetry/query',{method:'POST',body:JSON.stringify(q)}),progress:(p,n)=>{const label=document.querySelector('.gm-busy-card small');if(label)label.textContent=`Read ${p} archive pages · ${n} matching events`;}});
 try{report.capture=await call('/telemetry/lifecycle');}catch{report.capture={error:'status-unavailable'};}try{report.providerUsage=await call('/usage/providers?cached=1');}catch{report.providerUsage=null;}try{const remote=await fetch('/_profiles/v1/usage/profiles',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(10000)}).then(r=>r.ok?r.json():null);const {rows,registry}=readProfileLocal();report.profileUsage={kind:'current-UTC-month-snapshot',cloudAvailable:!!remote,lastSync:lastProfileSync,profiles:profileUsageSummary(remote,rows,registry).map((p,i)=>({profile:'profile-'+(i+1),today:p.today,month:p.month,localOnly:p.localOnly,pending:p.pending}))};}catch{report.profileUsage=null;}report.appVersion=VERSION;report.workerVersion=workerVersion;report.preparationUpload=uploadOutcome;const text=JSON.stringify(report),blob=new Blob([text],{type:'application/json'});preparedTelemetry={blob,name:activity?'telemetry-job-'+activity.id+'.json':'telemetry-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json'};
 const failed=exportOutcome(report,uploadOutcome)==='incomplete';const message=failed?'Some data could not be retrieved or uploaded. You can share the available file or try again.':report.coverage.events?'Export ready. All available archived records were read. More provider records may arrive later.':'Export ready. No matching records have been archived yet.';
 view='telemetry';selected=null;html(`<h2>Telemetry export</h2><section class="gm-card"><h3 class="${failed?'gm-warn':'success'}">${failed?'Export incomplete':'Export ready'}</h3><p>${e(message)}</p><p class="muted">${e(localTime(query.start))} to ${e(localTime(query.end))} · ${e(report.coverage.events)} records · ${e(fmtBytes(blob.size))}</p><button class="primary gm-full" data-act="telemetry-share-ready">${failed?'Share available file':'Share file'}</button><button class="gm-full" data-act="nav" data-id="${activity?'activity':'telemetry'}">Back</button></section>`);
}
async function action(b){const id=b.dataset.id,a=b.dataset.act;switch(a){case 'telemetry-quick':{const q=quickRange(Number(id));root.querySelector('#gm-start').value=q.start;root.querySelector('#gm-end').value=q.end;return;}case 'telemetry-period':{const input=root.querySelector('#gm-period-count');input.value=String(Math.max(1,Math.min(capturePeriods.length,Number(input.value||1)+Number(id))));updateRange();return;}case 'telemetry-prepare':{let start,end;const mode=root.querySelector('#gm-export-mode').value;if(mode==='periods'){const q=captureRange(capturePeriods,Number(root.querySelector('#gm-period-count').value));start=q.start;end=q.end;}else{start=parseInput(root.querySelector('#gm-start').value);end=parseInput(root.querySelector('#gm-end').value);}if(Date.parse(end)<=Date.parse(start)||Date.parse(end)-Date.parse(start)>31*86400000||Date.parse(end)>Date.now()+300000)throw Error('Choose a time range up to 31 days.');return prepareTelemetry({start,end,sources:[...SOURCES],jobId:null},null,Intl.DateTimeFormat().resolvedOptions().timeZone||'device-local',true,mode==='periods');}case 'telemetry-job':{const job=await call('/jobs/'+id);return prepareTelemetry(activityQuery(job),job,'UTC',true);}case 'check-release':{const update=globalThis.__APP_LAUNCHER__?.runUpdateButton;if(update)return update(b,{onError:message=>error(Error(message)),onStatus:label=>{const target=document.querySelector('.gm-busy-card strong');if(target)target.textContent=label;}});location.reload();return;}case 'telemetry-share-ready':if(!preparedTelemetry)throw Error('Prepare the file again.');return saveFile(preparedTelemetry.blob,preparedTelemetry.name);case 'telemetry-enable':case 'telemetry-disable':case 'telemetry-flush':{if(!unlock)throw Error('Unlock administrator access first');await call('/telemetry/lifecycle',{method:'POST',body:JSON.stringify({action:a==='telemetry-flush'?'flush':a==='telemetry-enable'?'enable':'disable'})});return render();}case 'share-export':return shareWorkspace(id);case 'share-source':return shareRemote(route(selected,'source',{ref}),selected+'-source.zip');case 'more-history':historyLimit+=10;return showActivity();case 'profile':{if(globalThis.__APP_LAUNCHER__){const {installProfileUI}=await import('/shared-profiles/ui.js');profileUI??=installProfileUI({adapter:{appName:'GitManager'}});return profileUI.open();}const response=await fetch('/_profiles/v1/status',{credentials:'same-origin',cache:'no-store'});const account=await response.json();html(`<h2>Google Drive profile</h2><p>${account.connected?'Connected as '+e(account.email):'Not connected'}</p><a class="gm-link gm-full" href="/_profiles/v1/auth/start?return=${encodeURIComponent(location.pathname+location.search)}">Connect Google Drive</a>${account.connected?'<button class="gm-full" data-act="signout">Sign out on this device</button>':''}`);return;}case 'signout':{if(!confirm('Sign out of Google Drive on this device?'))return;const r=await fetch('/_profiles/v1/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-PWA-CSRF':'1'},body:'{}'});if(!r.ok)throw Error('Sign out failed');location.reload();return;}case 'home':if(globalThis.__APP_LAUNCHER__)globalThis.__APP_LAUNCHER__.returnToLauncher();else{view='repos';selected=null;return render();}return;case 'nav':preparedTelemetry=null;view=id;selected=null;return render();case 'usage-refresh':{const [sync,googleRequest]=await Promise.all([globalThis.__APP_LAUNCHER__?import('/shared-profiles/profile-usage.js').then(m=>m.syncProfileUsage()).catch(()=>({state:'unavailable'})):Promise.resolve(null),call('/usage/google-refresh',{method:'POST'}).catch(()=>({failed:true}))]);html(await usagePage({force:true,sync,googleRequest}));return;}case 'refresh':return render();case 'repo':if(!repos.find(r=>r.name===id)?.head)throw Error('No main branch yet. Upload an initial-publication package in Updates.');selected=id;detail='commits';ref='main';dir='';page=1;return render();case 'back':selected=null;return render();case 'workflow':if(!unlock)throw Error('Unlock in Settings first');if(!confirm('Dispatch the current main workflow?'))return;await call('/repos/'+encodeURIComponent(selected)+'/workflows/'+id,{method:'POST'});return render();case 'export-setup':html(`<h2>Export repositories</h2><p>Choose any installed repositories. The export runs in GitHub Actions; share the workspace archive from Activity when completed. The .tar.gz contains complete Git metadata and needs only one tar extraction.</p>${repos.map(r=>`<label class="gm-check"><input type="checkbox" data-export="${e(r.name)}" ${r.head?'checked':'disabled'}> ${e(r.name)}</label>`).join('')}<label>Format<select id="gm-format"><option value="lightweight">Full Git, uninitialized submodules</option><option value="recursive">Full Git, initialized submodules</option><option value="bundle">Git bundles</option></select></label><button data-act="export-create">Start export</button>`);return;case 'export-create':{if(!unlock)throw Error('Unlock in Settings first');const names=[...root.querySelectorAll('[data-export]:checked')].map(x=>x.dataset.export);const job=await call('/exports',{method:'POST',body:JSON.stringify({repositories:names,format:root.querySelector('#gm-format').value,start:true})});return openNewActivity(job);}case 'verify':return verifyWorkspace();case 'detail':detail=id;dir='';page=1;return render();case 'use-ref':ref=id;detail='files';dir='';return render();case 'set-ref':ref=root.querySelector('#gm-ref').value;page=1;return render();case 'prev':page=Math.max(1,page-1);return render();case 'next':page++;return render();case 'file':dir=id;return render();case 'parent':dir=dir.split('/').slice(0,-1).join('/');return render();case 'download-file':return saveFile(new Blob([decode64(root._gmFile.content)]),dir.split('/').at(-1));case 'edit-file':return filePlan(dir,'put',new File([root.querySelector('#gm-edit').value],dir.split('/').at(-1)));case 'delete-file':return filePlan(dir,'delete');case 'revert':if(ref!=='main')throw Error('Revert must target main');plan=defaultPlan(repos.find(r=>r.name===selected),'revert');plan.updates[0].commit=id;upload=new File([''],'revert.txt');uploadIssue='';uploadNote='';selectedTarget='';needsTarget=false;advancedOpen=false;setPlan(plan);view='updates';return form();case 'unlock':{const field=root.querySelector('#gm-unlock');const password=field.value;field.value='';await call('/admin/unlock',{method:'POST',body:JSON.stringify({password})});await checkAdmin();if(!unlock)throw Error('Unlock cookie was not accepted. Check browser or gateway settings.');return render();}case 'lock':await call('/admin/lock',{method:'POST'});unlock=false;expiresAt=null;return render();case 'create':if(!unlock)throw Error('Unlock in Settings first');return openReview();case 'review-back':return closeReview();case 'review-confirm':{if(!unlock)throw Error('Unlock in Settings first');if(!reviewed)throw Error('Review the update again.');const f=new FormData();f.set('upload',reviewed.upload);f.set('plan',JSON.stringify(reviewed.plan));f.set('mode',reviewed.mode);const job=await call('/jobs',{method:'POST',body:f});closeReview();upload=null;uploadIssue='';uploadNote='';selectedTarget='';needsTarget=false;advancedOpen=false;setPlan(null);return openNewActivity(job);}case 'start':case 'resume':case 'cancel':if(!unlock)throw Error('Unlock in Settings first');if(!confirm(`${a==='start'?'Start approved job? Uploaded patches can modify workflows and deploy code.':a+' this job?'}`))return;await call('/jobs/'+id+'/'+a,{method:'POST'});return render();case 'verify-report':return saveFile(new Blob([JSON.stringify(root._gmVerification,null,2)],{type:'application/json'}),'workspace-verification.json');}}
const busyLabels={'usage-refresh':'Refreshing usage','check-release':'Checking app release','telemetry-prepare':'Reading archived telemetry','telemetry-job-upload':'Uploading pending and preparing telemetry','telemetry-job':'Preparing activity telemetry','telemetry-share-ready':'Sharing telemetry',repo:'Opening repository',refresh:'Refreshing workspace',nav:'Opening page',verify:'Verifying dependencies',unlock:'Validating administrator access',lock:'Locking administrator access',profile:'Opening Google Drive', 'telemetry-enable':'Enabling telemetry archive','telemetry-disable':'Disabling telemetry archive','telemetry-flush':'Uploading telemetry','telemetry-poll':'Collecting workflow telemetry','telemetry-probe':'Testing GitHub and Drive collection','telemetry-status-share':'Preparing telemetry status','review-confirm':'Creating update draft',start:'Starting remote job',resume:'Resuming job',cancel:'Cancelling remaining work','export-create':'Starting export','share-export':'Preparing export file','share-source':'Preparing source archive','export-job':'Preparing diagnostics',detail:'Loading repository details','set-ref':'Loading ref',file:'Opening file',parent:'Opening directory',workflow:'Dispatching workflow',prev:'Loading previous page',next:'Loading next page',back:'Opening repositories','more-history':'Loading activity history','use-ref':'Opening ref',home:'Opening workspace',signout:'Signing out'};
function beginBusy(label){const overlay=document.createElement('div');overlay.className='gm-busy-layer';overlay.setAttribute('role','status');overlay.setAttribute('aria-live','polite');overlay.innerHTML=`<div class="gm-busy-card"><span class="gm-spinner" aria-hidden="true"></span><strong>${e(label)}…</strong><small>Working with the service. Please keep this screen open for this request.</small></div>`;document.body.append(overlay);const d=root.querySelector('#gm-review[open]');let note;if(d){for(const button of d.querySelectorAll('button'))button.disabled=true;note=document.createElement('div');note.className='gm-review-busy';note.setAttribute('role','status');note.textContent=label+'…';d.querySelector('.gm-review-head').append(note);}return ()=>{overlay.remove();note?.remove();if(d?.isConnected)for(const button of d.querySelectorAll('button'))button.disabled=false;};}
async function perform(b){if(actionBusy||loading||b.disabled)return;actionBusy=true;uiEpoch++;let done=()=>{};try{if(b.dataset.locked){closeReview();view='settings';selected=null;done=beginBusy('Opening administrator settings');await render();root.querySelector('#gm-unlock')?.focus();return;}const a=b.dataset.act;if(busyLabels[a])done=beginBusy(busyLabels[a]);b.setAttribute('aria-busy','true');await action(b);}catch(err){if(err.name!=='AbortError'){const d=root.querySelector('#gm-review[open]');if(d){let msg=d.querySelector('.gm-review-error');if(!msg){msg=document.createElement('p');msg.className='gm-review-error gm-warn';msg.setAttribute('role','alert');d.querySelector('.gm-review-head').append(msg);}msg.textContent=err.message||String(err);}else error(err);}}finally{done();actionBusy=false;b.removeAttribute('aria-busy');markLocks();}}
root.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b)return;ev.preventDefault();void perform(b);});
root.addEventListener('input',ev=>{if(ev.target.id==='gm-period-count')updateRange();if(ev.target.id==='gm-plan'){manifestText=ev.target.value;reviewed=null;updateSummary();}});
root.addEventListener('change',async ev=>{if(actionBusy||loading)return;const target=ev.target;try{if(['gm-export-mode','gm-period-count'].includes(target.id)){updateRange();return;}if(target.id==='gm-mode'){updateMode=target.value;updateSummary();return;}if(target.id==='gm-target'){selectedTarget=target.value;if(target.value){const r=repos.find(x=>x.name===target.value),kind=upload.name.split('.').at(-1).toLowerCase();setPlan(defaultPlan(r,kind));}else setPlan(null);const editor=root.querySelector('#gm-plan');if(editor)editor.value=manifestText;updateSummary();return;}if(target.id==='gm-upload'&&target.files[0]){actionBusy=true;const done=beginBusy('Reading update package');try{await parseUpload(target.files[0]);}finally{done();actionBusy=false;}}if(target.id==='gm-file-put'&&target.files[0]){const f=target.files[0];filePlan((dir?dir+'/':'')+f.name,'put',f);}}catch(err){error(err);}});
poll=setInterval(()=>{if(document.hidden||loading||actionBusy||root.querySelector('#gm-review[open]'))return;if(unlock&&expiresAt&&Date.parse(expiresAt)<=Date.now()){unlock=false;markLocks();const label=root.querySelector('.gm-admin');if(label){label.innerHTML='Administrator locked · <button data-act="nav" data-id="settings">Unlock in Settings</button>';label.classList.remove('unlocked');}}const currentView=view,epoch=uiEpoch;call('/jobs').then(j=>{if(loading||actionBusy||epoch!==uiEpoch||view!==currentView||root.querySelector('#gm-review[open]'))return;if(view==='activity'&&JSON.stringify(j)!==JSON.stringify(jobsCache))showActivity(j);else{jobsCache=j;updateHeaderProgress();}}).catch(()=>{});},15000);const initialBusy=beginBusy('Connecting to GitManager');render().finally(initialBusy);
